import{_ as e,a as s,c as t,ac as n}from"./chunks/framework.BSuaGltH.js";const h=JSON.parse('{"title":"Redis 数据操作：结构、TTL、事务与 Lua","description":"以数据结构操作解释覆盖、过期和多步更新合同。","frontmatter":{"title":"Redis 数据操作：结构、TTL、事务与 Lua","description":"以数据结构操作解释覆盖、过期和多步更新合同。","showdocs":{"topics":[{"id":"redis","title":"Redis","link":"/topics/redis/"}],"kind":"数据与原子性","scope":"general","audience":"general","group":"数据库与存储","seriesTitle":"Redis 实践课程","summary":"以数据结构操作解释覆盖、过期和多步更新合同。","status":"active","related":[{"title":"Redis 操作与命令","link":"/middleware/redis/plus/ecosystem/redis-general-general","kind":"数据与原子性","scope":"general","audience":"general"},{"title":"Redis 数据类型命令速查","link":"/middleware/redis/plus/subjects/redis-data-cmd","kind":"数据与原子性","scope":"general","audience":"general"},{"title":"Redis 完整实践：Lua 原子限额与可重试 CLI","link":"/middleware/redis/plus/practice/quota","kind":"完整实践","scope":"general","audience":"general"},{"title":"Redis 游戏与通用后端场景","link":"/middleware/redis/pro/practice/game-scenarios","kind":"完整实践","scope":"general","audience":"general"},{"title":"Redis 持久化：RDB、AOF 与独立恢复","link":"/middleware/redis/persistence-and-recovery","kind":"数据与原子性","scope":"general","audience":"general"}],"prev":{"text":"Redis 起点与命令：隔离服务、连接与键空间","link":"/middleware/redis/base/basic/start"},"next":{"text":"Redis 完整实践：Lua 原子限额与可重试 CLI","link":"/middleware/redis/plus/practice/quota"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Redis 起点与命令：隔离服务、连接与键空间","link":"/middleware/redis/base/basic/start"},"next":{"text":"Redis 完整实践：Lua 原子限额与可重试 CLI","link":"/middleware/redis/plus/practice/quota"}},"headers":[],"relativePath":"middleware/redis/data-operations.md","filePath":"middleware/redis/data-operations.md"}'),r={name:"middleware/redis/data-operations.md"};function i(p,a,d,l,o,c){return s(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="redis-数据操作-结构、ttl、事务与-lua" tabindex="-1">Redis 数据操作：结构、TTL、事务与 Lua <a class="header-anchor" href="#redis-数据操作-结构、ttl、事务与-lua" aria-label="Permalink to &quot;Redis 数据操作：结构、TTL、事务与 Lua&quot;">​</a></h1><h2 id="part-1" tabindex="-1">Redis 数据结构、TTL 与原子性的选择 <a class="header-anchor" href="#part-1" aria-label="Permalink to &quot;Redis 数据结构、TTL 与原子性的选择 {#part-1}&quot;">​</a></h2><p>先了解各类型的特点与用途，请看基础理论中的 <a href="/middleware/redis/base/basic/data-types">Redis 数据类型</a>。本页侧重操作示例、TTL 与原子性的行为边界。</p><p>本轮仅全文静态审计，未安装依赖、启动服务、连接数据库或执行任何示例。下文实测、RED/GREEN及平台结果均为此前历史证据；本轮修改后的脚本未运行，命令与输出作为学习步骤和预期保留。</p><p>前置：<a href="/middleware/redis/base/basic/start#environment">独立服务与命令</a>。下面命令在 <code>docker exec showdocs-m4-redis-main redis-cli -e</code> 后追加；全部仅修改 <code>m4:</code> 教学键。数据类型的选择决定可用命令、时间复杂度和业务不变量，不能只看值是否能序列化。</p><h3 id="part-1-string" tabindex="-1">String 与计数器 <a class="header-anchor" href="#part-1-string" aria-label="Permalink to &quot;String 与计数器 {#part-1-string}&quot;">​</a></h3><p>String 保存字节串，可以是 UTF-8、整数文本或应用序列化后的 JSON。Redis 不会自动理解 JSON 内部字段；<code>INCR</code> 对整数文本原子加一，不能对 <code>&quot;1.5&quot;</code> 使用。金额若暂存在缓存中应先约定最小单位和上界，不能用浮点累加冒充精确账本。真实交易仍需持久存储的事务与审计约束。</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SET m4:counter 0</span></span>
<span class="line"><span>INCR m4:counter</span></span>
<span class="line"><span>INCRBY m4:counter 3</span></span>
<span class="line"><span>GET m4:counter</span></span>
<span class="line"><span>DEL m4:counter</span></span></code></pre></div><p>预期 <code>OK, 1, 4, &quot;4&quot;, 1</code>。INCR 是一个命令；先 GET、在应用加一、再 SET 是三个步骤，两个调用者会覆盖彼此结果。单个命令原子不自动扩展到调用者的业务流程。</p><h3 id="part-1-structures" tabindex="-1">Hash、List、Set 与 Sorted Set <a class="header-anchor" href="#part-1-structures" aria-label="Permalink to &quot;Hash、List、Set 与 Sorted Set {#part-1-structures}&quot;">​</a></h3><p>本节操作预期要求这些m4:教学键原先不存在；重复练习前只清理自己已确认的这些键，否则RPUSH、SADD、ZADD的计数或队列顺序会受旧值影响。</p><p>Hash 适合按字段读取对象，List 适合两端操作的序列，Set 表达唯一成员，Sorted Set 在唯一成员上维护 score 排序。不要用一种容器包装所有关系；独立过期需求往往意味着应拆键，而非把所有用户放一个大 Hash。</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HSET m4:user name Ada level 3</span></span>
<span class="line"><span>HGET m4:user name</span></span>
<span class="line"><span>RPUSH m4:queue a b</span></span>
<span class="line"><span>LPOP m4:queue</span></span>
<span class="line"><span>SADD m4:tags redis redis lua</span></span>
<span class="line"><span>SCARD m4:tags</span></span>
<span class="line"><span>ZADD m4:rank 10 alice 20 bob</span></span>
<span class="line"><span>ZRANGE m4:rank 0 -1 WITHSCORES</span></span>
<span class="line"><span>GET m4:user</span></span>
<span class="line"><span>DEL m4:user m4:queue m4:tags m4:rank</span></span></code></pre></div><p>HGET 返回 Ada，LPOP 返回 a（移除了它），SADD 返回 2，SCARD 返回 2，排名为 alice 10、bob 20。最后 GET Hash 返回 WRONGTYPE，原值不变。Set 无顺序保证，不能依赖 SMEMBERS 的输出排列；Sorted Set 相同 score 再按成员字节顺序排列，倒序命令和分页偏移要与产品排序规则一致。</p><p>List 的 LPOP 消费会立即移除：进程随后崩溃可能丢任务。需要确认、重新投递和消费组时应另学 Streams 或专用消息系统；本页没有把 List 演示声称为可靠队列。Hash 字段过期有版本差异，本课程使用整个键的 PEXPIRE，未演示的字段TTL不自动算已覆盖。</p><h3 id="part-1-ttl" tabindex="-1">TTL、覆盖与缓存 <a class="header-anchor" href="#part-1-ttl" aria-label="Permalink to &quot;TTL、覆盖与缓存 {#part-1-ttl}&quot;">​</a></h3><p>TTL 返回剩余秒数，PTTL 返回毫秒；<code>-1</code> 表示键存在且没有过期时间，<code>-2</code> 表示不存在。普通 SET 覆盖会移除原 TTL；<code>SET ... KEEPTTL</code> 可保留。Hash 的 HSET 修改字段不会重置整个键的 TTL。过期时间不是必须立即回收内存的计时器：Redis 结合访问时检查与主动过期，读到已到期键按不存在处理。</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SET m4:ttl value PX 30000</span></span>
<span class="line"><span>PTTL m4:ttl</span></span>
<span class="line"><span>SET m4:ttl replacement</span></span>
<span class="line"><span>TTL m4:ttl</span></span>
<span class="line"><span>PEXPIRE m4:ttl 30000</span></span>
<span class="line"><span>SET m4:ttl final KEEPTTL</span></span>
<span class="line"><span>PTTL m4:ttl</span></span>
<span class="line"><span>DEL m4:ttl</span></span>
<span class="line"><span>TTL m4:ttl</span></span></code></pre></div><p>预期第一次 PTTL 大于0且不超过30000，普通覆盖后 TTL=-1，KEEPTTL 后仍大于0，删除后 TTL=-2。网络和调度使剩余值变化，测试应断言区间而非等于30000。</p><p>Cache-aside 的基本流程是先读缓存，未命中读权威数据源，再 SET 加 TTL；更新时先提交数据源，再删除缓存。这仍可能在并发读回填时写入旧值，需要版本号、失效事件或其他协调策略。TTL 只限制陈旧时间，不保证强一致。对不存在对象可短暂缓存空值，热点回源可合并请求，TTL 加抖动可分散同时失效；这些策略都应有流量和失效需求依据。驱逐策略在内存不足时可能提前删除缓存；<code>noeviction</code> 则拒绝适用的写入。缓存可丢失，不能当资金账本。</p><h3 id="part-1-atomicity" tabindex="-1">Pipeline、MULTI 与 Lua 原子性 <a class="header-anchor" href="#part-1-atomicity" aria-label="Permalink to &quot;Pipeline、MULTI 与 Lua 原子性 {#part-1-atomicity}&quot;">​</a></h3><p>Pipeline 是批量发送减少网络往返，不提供多命令不可穿插。MULTI/EXEC 将队列中的命令连续执行；WATCH 提供乐观竞争检测，EXEC 返回空表示观察键变化，应重新读取并有界重试。执行阶段单条命令失败不会回滚其他成功命令。语法错误在排队阶段可能使整个事务被拒绝，两类错误不能混同。</p><p>Lua 脚本在服务器执行期间不被其他命令穿插，适合“读当前值→检查限额→写入并设过期”。这不是数据库式回滚：先 SET 再因 INCR 非整数失败，SET 仍然存在。先校验全部参数和类型，再写入，尽量把关联状态放同一个 Hash。脚本仍受 OOM、进程崩溃、故障切换及操作权限影响；客户端超时不能判断命令是否执行，盲目重试可能重复计数。</p><p>本课程<a href="/middleware/redis/plus/practice/quota#source">完整限额项目</a>用单个键、接受结果重放和窗口过期处理这些边界。脚本必须短小，长循环会阻塞其他客户端；所有键通过 KEYS 显式声明。Cluster 多键脚本要求同 slot；<code>{subject}</code> hash tag 仅帮助路由，不保证跨实例一致性。这里未验证集群。</p><h3 id="part-1-exercise" tabindex="-1">练习与参考解法 <a class="header-anchor" href="#part-1-exercise" aria-label="Permalink to &quot;练习与参考解法 {#part-1-exercise}&quot;">​</a></h3><p>提示：在两个命令之间画一个进程退出点，再观察原键的类型。</p><p>题目：为什么给计数器 INCR 后再 EXPIRE 不足以实现稳健限额？为什么 GET 字符串与 GET Hash 的失败应不同处理？</p><details><summary>参考解法</summary><p>两个独立命令之间进程可失败，留下无过期计数器；每次 EXPIRE 还可能无意延长窗口。把条件和首次过期写进 Lua 或使用合适的事务，仍须考虑运行错误不回滚。不存在字符串返回空是正常未命中；GET Hash 的 WRONGTYPE 是模式冲突，应该定位键所有者和类型，而非当未命中覆盖它。</p></details><p>一手资料：<a href="https://redis.io/docs/latest/develop/data-types/" target="_blank" rel="noopener noreferrer">数据类型</a>、<a href="https://redis.io/docs/latest/commands/expire/" target="_blank" rel="noopener noreferrer">EXPIRE</a>、<a href="https://redis.io/docs/latest/develop/using-commands/transactions/" target="_blank" rel="noopener noreferrer">事务</a>、<a href="https://redis.io/docs/latest/develop/programmability/eval-intro/" target="_blank" rel="noopener noreferrer">Lua</a>。国内云服务商对 Pipeline、事务的中文说明可见<a href="https://support.huaweicloud.com/intl/zh-cn/bestpractice-dcs/bestpractice-dcs-hk-pdf.pdf" target="_blank" rel="noopener noreferrer">华为云 Redis 使用最佳实践</a>，托管产品限制需另外对照，不能直接套到本机开源服务。</p><h2 id="part-2" tabindex="-1">Redis 事务与脚本入门 <a class="header-anchor" href="#part-2" aria-label="Permalink to &quot;Redis 事务与脚本入门 {#part-2}&quot;">​</a></h2><p>单个 <code>INCR</code> 可以完成计数加一，但“读取 → 应用计算 → 写回”是多步操作，其他客户端可能在中间修改数据。需要根据目的选择批量发送、事务或脚本。</p><h3 id="part-2-先区分四种能力" tabindex="-1">先区分四种能力 <a class="header-anchor" href="#part-2-先区分四种能力" aria-label="Permalink to &quot;先区分四种能力 {#part-2-先区分四种能力}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>能力</th><th>解决的问题</th><th>主要边界</th></tr></thead><tbody><tr><td>Pipeline</td><td>减少多次网络往返</td><td>不保证多条命令不会与其他客户端操作穿插</td></tr><tr><td>MULTI / EXEC</td><td>把排队的命令连续执行</td><td>执行时某条命令报错，不会回滚其他已成功命令</td></tr><tr><td>WATCH</td><td>发现读取后、提交前的键变化</td><td>冲突时事务不执行，应用需要重新读取并有限重试</td></tr><tr><td>Lua</td><td>在服务端完成读取、判断和写入</td><td>执行期间阻塞其他命令，脚本应短小并先校验再写入</td></tr></tbody></table><h3 id="part-2-一个简单事务" tabindex="-1">一个简单事务 <a class="header-anchor" href="#part-2-一个简单事务" aria-label="Permalink to &quot;一个简单事务 {#part-2-一个简单事务}&quot;">​</a></h3><p>以下步骤用于已连接的独立实验服务，本次文档整理未运行：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MULTI</span></span>
<span class="line"><span>SET learn:transaction:count 0</span></span>
<span class="line"><span>INCR learn:transaction:count</span></span>
<span class="line"><span>EXEC</span></span>
<span class="line"><span>GET learn:transaction:count</span></span>
<span class="line"><span>DEL learn:transaction:count</span></span></code></pre></div><p><code>MULTI</code> 后命令先排队，<code>EXEC</code> 返回每条命令的结果。没有其他客户端修改该教学键时，后续 <code>GET</code> 预期返回 <code>1</code>。<code>DISCARD</code> 可以取消尚未提交的队列。</p><h3 id="part-2-什么时候使用-watch-或-lua" tabindex="-1">什么时候使用 WATCH 或 Lua <a class="header-anchor" href="#part-2-什么时候使用-watch-或-lua" aria-label="Permalink to &quot;什么时候使用 WATCH 或 Lua {#part-2-什么时候使用-watch-或-lua}&quot;">​</a></h3><p>如果需要客户端读取一个值后计算新值，可以先 <code>WATCH</code> 该键，再读取、计算和提交事务。键在提交前发生相关变化时，<code>EXEC</code> 会放弃执行；不能无限重试。</p><p>如果条件判断可以在服务端完成，可以使用 Lua。例如检查计数是否达到限额，再决定是否增加。脚本访问的键通过 <code>KEYS</code> 显式传入，普通参数通过 <code>ARGV</code> 传入。脚本原子执行不代表具备错误回滚；写入后再报错，先前写入可能已经生效。</p><p>客户端超时也不能证明服务端没有执行。涉及重试时，需要另外设计幂等性。</p><p>继续阅读：<a href="#part-1-atomicity">事务与 Lua 的边界</a>、<a href="/middleware/redis/plus/practice/quota">Lua 限额实践</a>。参考：<a href="https://redis.io/docs/latest/develop/using-commands/transactions/" target="_blank" rel="noopener noreferrer">事务</a>、<a href="https://redis.io/docs/latest/develop/programmability/eval-intro/" target="_blank" rel="noopener noreferrer">Lua 脚本</a>、<a href="https://redis.io/docs/latest/develop/using-commands/pipelining/" target="_blank" rel="noopener noreferrer">Pipeline</a>。</p>`,42)])])}const m=e(r,[["render",i]]);export{h as __pageData,m as default};
